            endVertex: this.endVertex === null ? null : this.endVertex.id,
            signedAreaFragment: this.signedAreaFragment,
            forwardHalf: this.forwardHalf.serialize(),
            reversedHalf: this.reversedHalf.serialize(),
            visited: this.visited,
            data: this.data
